import{_ as i,o as e,c as t,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Developer Summit Quincy: RGW","description":"","frontmatter":{"title":"Ceph Developer Summit Quincy: RGW","date":"2021-04-09T00:00:00.000Z","updated":"2021-04-10T00:00:00.000Z","tags":["Ceph","RGW","Distributed Storage","Storage Cluster","Cloud Computing"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Developer_Summit_Quincy_-_RGW.md","filePath":"posts/2021/Ceph_Developer_Summit_Quincy_-_RGW.md","lastUpdated":1780459816000}'),r={name:"posts/2021/Ceph_Developer_Summit_Quincy_-_RGW.md"};function o(s,l,u,n,p,h){return e(),t("div",null,[...l[0]||(l[0]=[a('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-ceph-rgw-议程" tabindex="-1">会议主题：Ceph RGW 议程 <a class="header-anchor" href="#会议主题-ceph-rgw-议程" aria-label="Permalink to &quot;会议主题：Ceph RGW 议程&quot;">​</a></h4><h4 id="会议时间-具体时间" tabindex="-1">会议时间：[具体时间] <a class="header-anchor" href="#会议时间-具体时间" aria-label="Permalink to &quot;会议时间：[具体时间]&quot;">​</a></h4><h4 id="参会人员-列出主要参会人员" tabindex="-1">参会人员：[列出主要参会人员] <a class="header-anchor" href="#参会人员-列出主要参会人员" aria-label="Permalink to &quot;参会人员：[列出主要参会人员]&quot;">​</a></h4><h4 id="主要议题" tabindex="-1">主要议题： <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题：&quot;">​</a></h4><ol><li><p><strong>Swift API 与 S3 API 的支持情况</strong></p><ul><li>讨论了 Swift API 允许更新桶的元数据，但 S3 API 不支持特定操作，并探讨了扩展 S3 API 的可能性。</li></ul></li><li><p><strong>Dashboard 和 RGW 的功能更新</strong></p><ul><li>展示了 Dashboard 的最新功能，包括多站点配置下的性能图表、用户容量限制的可视化、桶配额管理等。</li><li>讨论了增强桶策略和后端管理的必要性，特别是配额管理和加密通知。</li></ul></li><li><p><strong>管理模块与 RGW 命令行接口</strong></p><ul><li>讨论了将所有 RGW 管理命令集成到 CLI 的可能性，以及管理模块与 RGW 管理 API 的关系。</li></ul></li><li><p><strong>Bucket 索引方案的改进</strong></p><ul><li>讨论了使用 SQLite 作为 Bucket 索引的可行性，以及 Bucket 索引性能的问题。</li></ul></li><li><p><strong>RGW 的 CLI 统一</strong></p><ul><li>讨论了将 RGW 管理命令统一到 CLI 的必要性和实施方案。</li></ul></li><li><p><strong>缓存策略</strong></p><ul><li>讨论了 D3N 和 D4N 缓存策略的进展和未来方向。</li></ul></li><li><p><strong>Zipper 项目</strong></p><ul><li>讨论了 Zipper 项目的当前状态和下一步计划，包括 API 的稳定性和未来发展。</li></ul></li><li><p><strong>Bucket 清单</strong></p><ul><li>讨论了实现 Bucket 清单功能的必要性和可能的实现策略。</li></ul></li><li><p><strong>RGW 去重</strong></p><ul><li>讨论了 RGW 去重的实现策略和可能的技术方案。</li></ul></li><li><p><strong>Pool 创建问题</strong></p><ul><li>讨论了 RGW 创建 Pool 时可能遇到的问题和解决方案。</li></ul></li><li><p><strong>Rook 和 Bucket Claims</strong></p><ul><li>讨论了 Rook 和 Bucket Claims 的相关问题。</li></ul></li><li><p><strong>测试策略</strong></p><ul><li>讨论了 RGW 测试的现状和未来可能的改进方向，特别是关于 API 覆盖和随机测试的需求。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>需要进一步讨论和规划如何扩展 S3 API。</li><li>确定增强 Dashboard 功能的具体需求，包括配额管理和加密通知。</li><li>需要对 RGW 管理命令进行重构，以便更好地集成到 CLI 中。</li><li>确定 Zipper 项目的下一步行动计划，包括 API 的稳定性和外部实现的兼容性。</li><li>需要进一步讨论 Bucket 清单功能的实现细节和策略。</li><li>确定 RGW 去重的实现策略和技术方案。</li><li>需要改进 RGW 测试策略，特别是增加随机测试和 API 覆盖。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>安排专门会议进一步讨论 S3 API 的扩展和 Dashboard 功能的增强。</li><li>开始 RGW 管理命令的重构工作，并制定详细的实施计划。</li><li>继续推进 Zipper 项目，确保 API 的稳定性和兼容性。</li><li>制定 Bucket 清单功能的详细实施方案。</li><li>确定 RGW 去重的具体技术方案和实施计划。</li><li>改进 RGW 测试策略，增加随机测试和 API 覆盖。</li></ul><h4 id="备注" tabindex="-1">备注： <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注：&quot;">​</a></h4><ul><li>会议中提到的具体技术细节和实现方案需要在后续的会议或工作中进一步细化和确认。</li><li>需要定期回顾和更新这些行动计划，确保项目的顺利进行。</li></ul><p><strong>会议结束时间：[具体时间</strong>]</p><p><strong>下次会议预定：[具体时间</strong>]</p>',14)])])}const _=i(r,[["render",o]]);export{d as __pageData,_ as default};
